package net.battlespades.app;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import net.battlespades.combat.*;
import net.battlespades.bot.BotState.StimulusKind;
import net.battlespades.entities.*;
import net.battlespades.match.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import net.battlespades.player.*;
import net.battlespades.protocol.*;
import net.battlespades.service.*;
import net.battlespades.session.*;
import net.battlespades.simulation.*;
import net.battlespades.world.BlockDamageModel.Cell;
/** Real standalone observation ports. Gameplay authorities are supplied by the hosted domain itself. */
final class DedicatedPorts implements StandardMatchDomain.Services,LifeRuntime.Effects,HostedInputRuntime.Ports,HostedPlayerRuntime.Ports,HostedEntityRuntime.Ports,HostedCombatRuntime.Ports {
    private final DedicatedServer server;private final String label;private boolean closed;private StandardMatchDomain domain;
    DedicatedPorts(DedicatedServer server,String label){this.server=server;this.label=label;}
    void bind(StandardMatchDomain value){if(domain!=null)throw new IllegalStateException("Ports already bound");domain=Objects.requireNonNull(value);}
    private StandardMatchDomain match(){return Objects.requireNonNull(domain,"Ports are not bound");}
    private void observe(String text){server.log(LoggingRuntime.Level.DEBUG,label,()->text,null);}
    public boolean admin(int id){return server.application().administration().map(a->a.admin(id)).orElse(false);}public boolean stopping(){return closed||server.stopping();}
    public CompletionStage<Void> plugin(ModeEvents.Event e){observe(e.name());return CompletableFuture.completedFuture(null);}
    public void matchStarted(){server.bots().ifPresent(b->b.phase("start",0));server.log(LoggingRuntime.Level.INFO,label,()->"Match started",null);}public void matchEnded(Integer winner){server.log(LoggingRuntime.Level.INFO,label,()->"Match ended; winner="+winner,null);}public void rebuildResources(){observe("resources rebuilt");}
    public void endVote(double wall){throw new IllegalStateException("Voting service must be bound");}public void vote(double wall){throw new IllegalStateException("Voting service must be bound");}public void scheduleEnd(Integer winner){throw new IllegalStateException("Ending service must be bound");}public CompletionStage<Void> cancelEnd(){return CompletableFuture.completedFuture(null);}
    public void zombieRound(HostedZombieRuntime.RoundObservation e){observe("zombie round");}public void vipRound(HostedVipRuntime.RoundObservation e){observe("vip round");}public void demolitionRepair(PlayerLife p,int count){observe("demolition repair "+count);}public void hillEvent(HostedZoneRuntime.HillEvent e){observe("hill event");}public void carryObservation(HostedCarryRuntime.Observation e){observe("carry event");}
    public void escapeWatch(){observe("escape watch");}public void reveal(PlayerLife p,Consumer<GamePacket> send){observe("reveal "+p.id());}public void resetResultBaselines(){observe("result baselines reset");}public void scheduleResults(Integer winner){observe("offline result; winner="+winner);}public void retireDeployables(PlayerLife p){observe("deployables retired "+p.id());}
    public void failure(String label,Throwable error){server.failure(label,error);}public void close(){closed=true;}
    public void beforeSpawn(PlayerLife p){observe("before spawn "+p.id());}public void spawned(PlayerLife p){observe("spawn "+p.id());}public void died(PlayerLife v,PlayerLife a,int type,int presentation,boolean enemy){server.bots().ifPresent(b->b.killed(v,a,type));}public void damaged(LifeRuntime.DamageEvidence e){observe("damage");}public void healed(LifeRuntime.HealingEvidence e){observe("heal");}public void beforeDeath(LifeRuntime.DeathEvidence e){observe("before death");}public void transitionCredited(PlayerLife v,PlayerLife a,int type){observe("transition death");}public void respawnFailed(PlayerLife p,RuntimeException e){failure("respawn "+p.id(),e);}
    public void reset(PlayerLife p){observe("reset "+p.id());}public void observedInput(PlayerLife p,LiveClientInput input,int tick){observe("input "+p.id());}public void packet(PlayerLife p,GamePacket packet){observe("unhandled optional packet "+packet.id()+" from "+p.id());}public void forget(PlayerLife p){observe("forget "+p.id());}public boolean mountedGun(PlayerLife p){return match().inputs().mounted(p);}public void rejectedTool(PlayerLife p,int requested,int held){observe("rejected tool "+requested+" held="+held);}public void movementReport(PlayerLife p,String kind,Map<String,Double> detail){observe("movement "+p.id()+" "+kind+" "+detail);}
    public void paintbrush(PlayerLife p,LiveClientInput input){observe("editor-only paintbrush rejected outside creator");}
    public PlayerSnapshot.Presentation presentation(PlayerLife p){return new PlayerSnapshot.Presentation(p.inventory().tool(),p.pickupId(),false,false,false,false,true,match().inputs().mounted(p));}
    public List<EntityRecord> entities(){return match().entities().registry().all().stream().filter(e->e.alive&&e.wireVisible&&e.kind.equals("projectile")).map(MapEntity::toWireEntity).toList();}public List<WorldUpdate.TurretRow> turrets(){return match().entities().turrets();}public void delivered(int packets,long bytes){observe("world delivery "+packets+"/"+bytes);}
    public void lagHistory(PlayerLife p,int tick){observe("lag history "+p.id());}public void housekeeping(PlayerLife p){observe("housekeeping "+p.id());}public int pendingTerrainMutations(){return match().construction().mutations().metrics().pending();}public void report(PlayerLife p,String kind,boolean enforced){observe("anticheat "+p.id()+" "+kind+" enforced="+enforced);}public void afterMove(PlayerLife p,double dt){observe("move "+p.id());}public void observePhysics(PlayerLife p,double now){server.bots().ifPresent(b->b.observePhysics(p,now));}
    public boolean transitionBusy(){return server.transitions().busy();}public TeamBalancer.Bots bots(){return server.bots().map(HostedBotDirector::balancing).orElse(null);}public boolean hearingEnabled(){return server.bots().isPresent();}public void blockDestroyed(GameplaySounds.Position at,int source,int team,double lifetime){server.bots().ifPresent(b->b.stimulus(StimulusKind.BLOCK_DESTROYED,new Vector(at.x(),at.y(),at.z()),source,team,net.battlespades.bot.BotStimulusBus.HEARING_DISTANCE,lifetime));}public void updateBotSkill(double now){server.bots().ifPresent(b->b.updateSkill(now));}public void anticheatReport(double now){observe("review tick");}
    public Object crateBaseline(PlayerLife p){return p.health();}public void crateCollected(PlayerLife p,int award,Object baseline){observe("crate collected "+p.id());}public void resourcesRebuilt(MapResourceService.Result result){observe("map resources rebuilt");}public void skippedEntityTicks(long count){server.telemetry().metrics().add(RuntimeMetrics.Counter.skipped_entity_ticks,count);}
    public void blastStimulus(Vector at,int source,int team,double radius,double lifetime){server.bots().ifPresent(b->b.stimulus(StimulusKind.EXPLOSION,at,source,team,radius,lifetime));}public Object beginBlast(PlayerLife p,int type,Vector at){return new Object();}public void endBlast(Object scope){observe("blast complete");}public void blastScopeFault(String phase){failure("blast scope "+phase,new IllegalStateException("Unbalanced blast scope"));}
    public Iterable<? extends HitTrace.Corpse> corpses(){return match().corpses().hittable();}public boolean explodeCorpse(HitTrace.Corpse c,PlayerLife p,boolean show){return match().corpses().explode(c,p,show);}public void clearDisguise(PlayerLife p){observe("disguise cleared "+p.id());}public void shieldImpact(PlayerLife p,Vector at,boolean melee){observe("shield impact "+p.id());}public void observeShot(PlayerLife p,ShootPacket packet,double now){observe("shot "+p.id());}public void resolved(ShotTally.Resolved e){observe("shot resolved");}public void validationReport(PlayerLife p,ShotValidation.Event e){observe("shot validation "+p.id()+" "+e.kind());}public void rewindReport(PlayerLife p,LagCompensation.Diagnostic e){observe("rewind "+p.id());}
    public void shotStimulus(Vector at,int source,int team,double radius,double lifetime){server.bots().ifPresent(b->b.stimulus(StimulusKind.SHOT,at,source,team,radius,lifetime));}public void dropped(PlayerLife p,ShootPacket packet,String reason){observe("dropped shot "+p.id()+" "+reason);}public void cadenceDropped(PlayerLife p,ShootPacket packet,double now){observe("cadence "+p.id());}public void nearMiss(PlayerLife p,ShootPacket packet,Vector at,Vector direction,CombatCatalog.Profile profile){observe("near miss "+p.id());}public void rejected(PlayerLife p,String reason){observe("rejected "+p.id()+" "+reason);}public void blocksDestroyed(PlayerLife p,List<Cell> removed,List<Cell> collapsed,List<List<Cell>> chunks,Integer tool){observe("terrain removed="+removed.size()+" collapsed="+collapsed.size());}
}
